<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyInvoiceAmounts.php';require_once __DIR__.'/CompanyBankReceiptComponents.php';require_once __DIR__.'/issuers/IssuerResourceAccess.php';

/** Exact company-only position. Cash, genuine credits and bank reductions remain distinct. */
final class CompanyInvoiceBalance
{
    public function __construct(private $db,private string $p){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid table prefix');}
    public function tables():array{$tables=array_merge((new CompanyBankReceiptComponents($this->db,$this->p))->tables(),['credits']);foreach(['creditnotes','company_credit_documents','company_credit_entries'] as $table)if($this->db->table_exists($this->p.$table))$tables[]=$table;return array_values(array_unique($tables));}
    private function rows(string $sql,array $args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
    private static function minor($value):int{try{$n=CompanyInvoiceAmounts::minor((string)$value);if($n<0||$n>CompanyInvoiceAmounts::MAX)throw new DomainException();return $n;}catch(Throwable $e){throw new DomainException('company_invoice_balance_review');}}
    private static function add(int &$target,int $value):void{if($value>CompanyInvoiceAmounts::MAX-$target)throw new DomainException('company_invoice_balance_review');$target+=$value;}
    /** Caller owns the complete boundary; false is limited to intermediate canonical projections. */
    public function inOwned($issuer,$actor,$invoice,bool $verifyStatus=true):array
    {
        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$invoice=IssuerPolicy::id($invoice);IssuerTransaction::assertOwned($this->db,$this->p,$this->tables());$acl=new IssuerResourceAccess($this->db,$this->p);if(!$acl->can($issuer,$actor,'invoices','view'))throw new DomainException('company_invoice_access_denied');
        if(!$this->rows('SELECT i.id FROM '.$this->p.'invoices i JOIN '.$this->p.'issuers_invoice_documents d ON d.invoice_id=i.id AND d.issuer_id=i.issuer_id WHERE i.id=? AND i.issuer_id=? FOR UPDATE',[$invoice,$issuer]))throw new DomainException('company_invoice_access_denied');
        $components=(new CompanyBankReceiptComponents($this->db,$this->p))->forInvoiceInOwned($issuer,$actor,$invoice);$result=$this->calculate($issuer,$invoice,$components,$verifyStatus);if(!$acl->can($issuer,$actor,'invoices','view'))throw new DomainException('company_invoice_access_denied');return $result;
    }
    /** A contact is never impersonated as staff. The final portal service revalidates native permission1. */
    public function portalInOwned(CompanyPortalInvoices $portal,array $session,$issuer,$invoice):array
    {
        $issuer=IssuerPolicy::id($issuer);$invoice=IssuerPolicy::id($invoice);IssuerTransaction::assertOwned($this->db,$this->p,array_merge($this->tables(),$portal->balanceTables()));$portal->balanceIdentityInOwnedTransaction($session,$issuer,$invoice,$this->db,$this->p);$components=(new CompanyBankReceiptComponents($this->db,$this->p))->forPortalInOwned($portal,$session,$issuer,$invoice);$result=$this->calculate($issuer,$invoice,$components,true);$portal->balanceIdentityInOwnedTransaction($session,$issuer,$invoice,$this->db,$this->p);return $result;
    }
    private function calculate(int $issuer,int $invoice,array $components,bool $verifyStatus):array
    {
        $parent=$this->rows('SELECT i.id,i.issuer_id,i.clientid,i.currency,i.total,i.status FROM '.$this->p.'invoices i JOIN '.$this->p.'issuers_invoice_documents d ON d.invoice_id=i.id AND d.issuer_id=i.issuer_id WHERE i.id=? AND i.issuer_id=? FOR UPDATE',[$invoice,$issuer])[0]??null;if(!$parent)throw new DomainException('company_invoice_access_denied');(new CompanyCurrencyUnits($this->db,$this->p))->resolveRead($parent['currency']);
        $allComponents=$this->rows('SELECT issuer_id,payment_id FROM '.$this->p.'company_bank_receipt_components WHERE invoice_id=? FOR UPDATE',[$invoice]);if(count($allComponents)!==count($components))throw new DomainException('company_invoice_balance_review');foreach($allComponents as $c)if((int)$c['issuer_id']!==$issuer||!isset($components[(int)$c['payment_id']]))throw new DomainException('company_invoice_balance_review');
        $total=self::minor($parent['total']);if($total<1)throw new DomainException('company_invoice_balance_review');$paid=0;$applied=0;$discount=0;$abatement=0;$seen=[];$paymentsSeen=[];$creditsSeen=[];$applySeen=[];
        foreach($this->rows('SELECT id,invoiceid,amount,paymentmode,paymentmethod,date,transactionid,note FROM '.$this->p.'invoicepaymentrecords WHERE invoiceid=? ORDER BY id FOR UPDATE',[$invoice]) as $payment){
            $id=(int)$payment['id'];$paymentsSeen[$id]=$payment['paymentmode'];$proof=$this->rows('SELECT issuer_id,invoice_id,request_key,input_hash FROM '.$this->p.'company_payment_receipts WHERE payment_id=? FOR UPDATE',[$id]);if(count($proof)!==1||(int)$proof[0]['issuer_id']!==$issuer||(int)$proof[0]['invoice_id']!==$invoice)throw new DomainException('company_invoice_balance_review');$current=self::minor($payment['amount']);$original=$current;
            foreach(($this->db->table_exists($this->p.'company_credit_entries')?$this->rows("SELECT issuer_id,invoice_id,amount FROM {$this->p}company_credit_entries WHERE kind='manual_reverse' AND native_id=? FOR UPDATE",[$id]):[]) as $entry){if((int)$entry['issuer_id']!==$issuer||(int)$entry['invoice_id']!==$invoice||$payment['paymentmode']!=='company_manual')throw new DomainException('company_invoice_balance_review');self::add($original,self::minor($entry['amount']));}
            $payload=['invoiceid'=>$invoice,'amount'=>CompanyInvoiceAmounts::decimal($original),'paymentmode'=>$payment['paymentmode'],'paymentmethod'=>$payment['paymentmethod'],'date'=>$payment['date'],'transactionid'=>$payment['transactionid'],'note'=>$payment['note']];if(!hash_equals($proof[0]['input_hash'],hash('sha256',json_encode($payload,JSON_THROW_ON_ERROR))))throw new DomainException('company_invoice_balance_review');self::add($paid,$current);
            if($payment['paymentmode']==='bb_cnab240_components_reviewed'){if(!isset($components[$id]))throw new DomainException('company_invoice_balance_review');$component=$components[$id];if(self::minor($component['cash_principal'])!==$current)throw new DomainException('company_invoice_balance_review');self::add($discount,self::minor($component['discount']));self::add($abatement,self::minor($component['abatement']));$seen[$id]=true;}elseif(isset($components[$id]))throw new DomainException('company_invoice_balance_review');
        }
        // Simple FKs do not prove that a receipt's invoice and payment share the same parent.
        $invoiceReceipts=$this->rows('SELECT issuer_id,payment_id FROM '.$this->p.'company_payment_receipts WHERE invoice_id=? FOR UPDATE',[$invoice]);if(count($invoiceReceipts)!==count($paymentsSeen))throw new DomainException('company_invoice_balance_review');foreach($invoiceReceipts as $receipt)if((int)$receipt['issuer_id']!==$issuer||!isset($paymentsSeen[(int)$receipt['payment_id']]))throw new DomainException('company_invoice_balance_review');
        if(count($seen)!==count($components))throw new DomainException('company_invoice_balance_review');
        foreach($this->rows('SELECT id,invoice_id,credit_id,amount FROM '.$this->p.'credits WHERE invoice_id=? ORDER BY id FOR UPDATE',[$invoice]) as $movement){
            $credit=$this->rows('SELECT c.id FROM '.$this->p.'creditnotes c JOIN '.$this->p.'company_credit_documents d ON d.credit_id=c.id AND d.issuer_id=c.issuer_id WHERE c.id=? AND c.issuer_id=? AND c.clientid=? AND c.currency=? FOR UPDATE',[$movement['credit_id'],$issuer,$parent['clientid'],$parent['currency']]);if(count($credit)!==1)throw new DomainException('company_invoice_balance_review');
            $entries=$this->rows("SELECT request_key,issuer_id,credit_id,invoice_id,amount FROM {$this->p}company_credit_entries WHERE kind='apply' AND native_id=? FOR UPDATE",[$movement['id']]);if(count($entries)!==1)throw new DomainException('company_invoice_balance_review');$entry=$entries[0];$creditsSeen[(int)$movement['id']]=$entry['request_key'];$applySeen[$entry['request_key']]=(int)$movement['id'];if((int)$entry['issuer_id']!==$issuer||(int)$entry['credit_id']!==(int)$movement['credit_id']||(int)$entry['invoice_id']!==$invoice)throw new DomainException('company_invoice_balance_review');$remaining=self::minor($entry['amount']);
            foreach($this->rows("SELECT issuer_id,credit_id,invoice_id,native_id,amount FROM {$this->p}company_credit_entries WHERE kind='unapply' AND parent_key=? FOR UPDATE",[$entry['request_key']]) as $reverse){$amount=self::minor($reverse['amount']);if((int)$reverse['issuer_id']!==$issuer||(int)$reverse['credit_id']!==(int)$movement['credit_id']||(int)$reverse['invoice_id']!==$invoice||(int)$reverse['native_id']!==(int)$movement['id']||$amount>$remaining)throw new DomainException('company_invoice_balance_review');$remaining-=$amount;}
            if(self::minor($movement['amount'])!==$remaining)throw new DomainException('company_invoice_balance_review');self::add($applied,$remaining);
        }
        if($this->db->table_exists($this->p.'company_credit_entries'))foreach($this->rows("SELECT request_key,issuer_id,kind,native_id,parent_key FROM {$this->p}company_credit_entries WHERE invoice_id=? AND kind IN ('apply','unapply','manual_reverse') FOR UPDATE",[$invoice]) as $entry){$id=(int)$entry['native_id'];if((int)$entry['issuer_id']!==$issuer)throw new DomainException('company_invoice_balance_review');if($entry['kind']==='apply'&&($creditsSeen[$id]??null)!==$entry['request_key'])throw new DomainException('company_invoice_balance_review');if($entry['kind']==='unapply'&&($applySeen[$entry['parent_key']]??null)!==$id)throw new DomainException('company_invoice_balance_review');if($entry['kind']==='manual_reverse'&&($paymentsSeen[$id]??null)!=='company_manual')throw new DomainException('company_invoice_balance_review');}
        $used=0;foreach([$paid,$applied,$discount,$abatement] as $n)self::add($used,$n);if($used>$total)throw new DomainException('company_invoice_balance_review');$left=$total-$used;$status=(int)$parent['status'];if(!in_array($status,[1,2,3,4,5,6],true)||(($status===5||$status===6)&&$used>0))throw new DomainException('company_invoice_balance_review');if($verifyStatus&&(($status===2&&$left!==0)||($status===3&&($left===0||$left===$total))||(in_array($status,[1,4],true)&&$left!==$total)))throw new DomainException('company_invoice_balance_review');
        return ['invoice_id'=>$invoice,'issuer_id'=>$issuer,'total'=>CompanyInvoiceAmounts::decimal($total),'received'=>CompanyInvoiceAmounts::decimal($paid),'applied_credit'=>CompanyInvoiceAmounts::decimal($applied),'settlement_discount'=>CompanyInvoiceAmounts::decimal($discount),'settlement_abatement'=>CompanyInvoiceAmounts::decimal($abatement),'noncash_reductions'=>CompanyInvoiceAmounts::decimal($discount+$abatement),'receivable'=>CompanyInvoiceAmounts::decimal($left),'components'=>$components];
    }
}
